    {"name": 'Vouchers', "output_path": 'Vouchers.xml', "output_is_json": False, "shape": 'group', "groups": [    {"name": 'Voucher', "selector": 'div.voucher', "repeating": True, "children": [        {"name": 'Code', "selector": '.code', "mode": 'text', "transform": [], "download": False, "maxDownloadSizeBytes": None, "allowedContentTypes": [], "hiddenFromOutput": False},    ]},], "hardening": {"enabled": True, "has_baseline": True, "checks": [{"kind": 'noResult', "severity": 'Warning'}, {"kind": 'baseline', "severity": 'Warning', "dropThreshold": 0.3}, {"kind": 'blocking', "severity": 'Warning', "minBodyLength": None, "blockPhrases": ['Access Denied']}]}, "change_detection": {"enabled": False, "notify": None, "smtp_host_env_var": None, "smtp_port_env_var": None, "smtp_username_env_var": None, "smtp_password_env_var": None, "from_env_var": None, "to_env_var": None, "webhook_url_env_var": None}},
